{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "There is limited evidence in peer-reviewed literature on modelling for malaria optimization in limited resource settings. The country focus of the modelling studies included in the review were not representative of the burden of malaria in sub-Saharan Africa.",
      "reason": "The manuscript describes gaps/limitations in the existing literature (limited evidence; lack of representative country coverage), but does not clearly describe “important uncertainties” in the current state of knowledge beyond these stated limitations."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets. This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The abstract explains why the review is needed (stalled progress and constrained budgets) and states the review’s purpose/need to identify and characterise models and their strengths/limitations."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not mention prior similar systematic reviews or explain how a previous review supports the need for this current review (e.g., updates/replications)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets.",
      "reason": "The review rationale in the retrieved evidence is about optimization models for resource allocation, not describing a proposed mechanism of action of a specific intervention in an intervention-effects sense."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not provide a logic model showing hypothesised relationships between intervention components and outcomes; however, there is also no indication in the retrieved evidence that the review rationale requires a logic model for complex interventions/delivery contexts."
    }
  ],
  "confidence": 52
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review provides an explicit research question and a main aim in the introduction/methods context."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The evidence shows the review objective is to identify/characterize optimization models (including strengths/limitations), not to state planned intervention-effect comparisons using PICO (or a variant)."
    }
  ],
  "confidence": 78
}

